// Some portions generated by Co-Pilot
"use client";

import { useState, useSyncExternalStore } from "react";
import Image from "next/image";
import { useTranslations } from "next-intl";
import { FiCheck } from "react-icons/fi";
import vendors from "@/data/marketplace.json";
import getVendorIdentifier from "@/utils/vendors";
import { shuffle } from "@/utils/shuffle";

export type VendorName = (typeof vendors)[number]["name"];
export interface Vendor {
  name: VendorName;
  icon: string;
  iconPadding?: string;
}
interface VendorSelectorProps {
  selectedVendorIdentifiers: string[];
  setSelectedVendorIdentifiers: (identifiers: string[]) => void;
}
const subscribe = () => () => {};
const getClientSnapshot = () => true;
const getServerSnapshot = () => false;

const VendorSelector = ({
  selectedVendorIdentifiers,
  setSelectedVendorIdentifiers,
}: VendorSelectorProps) => {
  const [shuffledVendors] = useState<Vendor[]>(() => shuffle([...vendors]));
  const hydrated = useSyncExternalStore(
    subscribe,
    getClientSnapshot,
    getServerSnapshot,
  );
  const displayedVendors: Vendor[] = hydrated ? shuffledVendors : vendors;
  const t = useTranslations("Marketplace.VendorSelector");
  const tReleases = useTranslations("Marketplace.Releases");
  return (
    <div className="mt-4 border-t border-white/10 pt-4">
      <div className="mb-2 flex flex-wrap items-center justify-between gap-3 text-xs text-grey">
        <span className="font-medium">{tReleases("vendor")}</span>
        <span>
          {t("vendors-selected", {
            selected: selectedVendorIdentifiers.length,
            total: displayedVendors.length,
          })}
        </span>
      </div>
      <div
        role="group"
        aria-label={tReleases("vendor")}
        className="flex flex-wrap gap-2"
      >
        {displayedVendors.map((vendor) => {
          const identifier = getVendorIdentifier(vendor);
          const selected = selectedVendorIdentifiers.includes(identifier);
          return (
            <button
              key={identifier}
              type="button"
              title={vendor.name}
              aria-pressed={selected}
              onClick={() =>
                setSelectedVendorIdentifiers(
                  selected
                    ? selectedVendorIdentifiers.filter(
                        (value) => value !== identifier,
                      )
                    : [...selectedVendorIdentifiers, identifier],
                )
              }
              className={`inline-flex min-h-12 items-center gap-2 rounded-xl border px-3 py-2 text-sm transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink ${selected ? "border-pink/40 bg-pink/5 text-white" : "border-white/10 text-grey hover:border-white/30 hover:text-white"}`}
            >
              <span
                className={`relative flex h-7 w-7 items-center justify-center rounded-lg bg-white p-1 ${selected ? "" : "opacity-50 grayscale"}`}
              >
                <Image
                  src={`/images/vendors/${vendor.icon}`}
                  alt=""
                  width={20}
                  height={20}
                  className="h-5 w-5 object-contain"
                  style={
                    vendor.iconPadding
                      ? { padding: vendor.iconPadding }
                      : undefined
                  }
                />
              </span>
              <span>{vendor.name}</span>
              <FiCheck
                aria-hidden="true"
                className={selected ? "text-[#ff91b7]" : "invisible"}
              />
            </button>
          );
        })}
      </div>
    </div>
  );
};
export default VendorSelector;
